local a=require"system.filesystem"local b=require"system.hardware"local c=require"system.log"local d=c.create("diskmgr",true)local e={}local function f(g)local h=b.call(g,"getState")if h and h.id then local i="/media/"if h.label then i=i..h.label else i=i..h.id end;local j,k=pcall(function()a.mkdir(i)a.mount("drivefs",g,i,{})e[g]=i end)if j then d.info("Mounted drive "..g.." to "..i)else d.error("Could not mount drive: "..k)end end end;local function l(i,m)if b.hasType(i,"drive")or b.hasType(i,"modem")then b.listen(i)end;if m and b.hasType(i,"drive")then f(i)end;for n,o in ipairs(b.children(i))do l(i.."/"..o,m)end end;b.listen("/")l("/",true)while true do local p,q=coroutine.yield()if p=="disk"then f(q.device)elseif p=="disk_eject"and e[q.device]then a.unmount(e[q.device])a.remove(e[q.device])e[q.device]=nil elseif p=="device_added"then l(q.device,false)end end
